-- public.standing_crate(p_world uuid, p_uid uuid, p_x double precision, p_y double precision)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.standing_crate(p_world uuid, p_uid uuid, p_x double precision, p_y double precision)
 RETURNS bigint
 LANGUAGE sql
 STABLE
AS $function$
  select pl.id from placed pl, my_deed(p_world, p_uid) dd
   where dd.world_id is not null and pl.world_id = p_world
     and pl.kind = 'furniture' and pl.sub = 'creature_crate' and pl.creature is null and pl.made_by = p_uid
     and abs(pl.x - dd.x) <= dd.radius and abs(pl.y - dd.y) <= dd.radius
   order by (pl.cx - p_x) ^ 2 + (pl.cy - p_y) ^ 2, pl.id
   limit 1
$function$
